def resolve_image_path(base_dir, rel_path):
    """Cyrillic filenames on disk may be NFD-normalized (common when files
    were added from macOS) while a hand-typed/copy-pasted path string here
    is NFC — same visible text, different bytes, so a plain Path.exists()
    can silently miss the file. Try both normalizations before giving up.
    """
    for form in ('NFC', 'NFD'):
        candidate = base_dir / unicodedata.normalize(form, rel_path)
        if candidate.exists():
            return candidate
    return base_dir / rel_path


def seed_slides(apps, schema_editor):
    HeroSlide = apps.get_model('pages', 'HeroSlide')
    if HeroSlide.objects.exists():
        return
    static_dir = Path(settings.BASE_DIR) / 'static'
    for data in SLIDES:
        data = dict(data)
        image_path = resolve_image_path(static_dir, data.pop('image_path'))
        slide = HeroSlide(**data)
        if image_path.exists():
            with open(image_path, 'rb') as f:
                slide.image.save(image_path.name, File(f), save=False)
        slide.save()


